CREATE TABLE IF NOT EXISTS hr_user_employee_map(map_id TEXT PRIMARY KEY,user_id TEXT NOT NULL,employee_id TEXT NOT NULL,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,employee_id));
CREATE TABLE IF NOT EXISTS hr_shift_roster(roster_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,employee_id TEXT NOT NULL,shift_id TEXT NOT NULL,work_date DATE NOT NULL,status TEXT NOT NULL DEFAULT 'PLANNED',created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(employee_id,work_date));
CREATE TABLE IF NOT EXISTS hr_calendar(calendar_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,calendar_date DATE NOT NULL,day_type TEXT NOT NULL,paid BOOLEAN NOT NULL DEFAULT TRUE,notes TEXT,UNIQUE(organization_id,entity_id,calendar_date));
CREATE TABLE IF NOT EXISTS hr_labour_variance(variance_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,batch_id TEXT NOT NULL,work_date DATE NOT NULL,standard_hours NUMERIC NOT NULL,actual_hours NUMERIC NOT NULL,standard_cost NUMERIC NOT NULL,actual_cost NUMERIC NOT NULL,hours_variance NUMERIC NOT NULL,cost_variance NUMERIC NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',approved BOOLEAN NOT NULL DEFAULT FALSE,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_hr_roster_scope ON hr_shift_roster(organization_id,entity_id,work_date,employee_id);
CREATE INDEX IF NOT EXISTS ix_hr_variance_batch ON hr_labour_variance(organization_id,entity_id,batch_id,work_date);
